{
  "explanation": "Two functions are inverses when each one undoes the other: e^(ln x) = x and ln(e^x) = x. Since inverting a function swaps the roles of x and y, the graph of an inverse is the mirror image of the original across the line y = x — every point (a, e^a) on y = e^x has a twin (e^a, a) on y = ln(x). Watch the sample points reflect across the line, then drag either colored dot (or use the slider): the pair always stays symmetric about y = x, with the connecting segment perpendicular to and bisected by that mirror line.",
  "manimCode": "// Axes on the left side of the frame
const axes = new Axes({ xRange: [-3, 4, 1], yRange: [-3, 4, 1], xLength: 7, yLength: 7, tips: true });
axes.moveTo([-1.8, 0, 0]);

// World <-> data coordinate conversion (used for dragging along the curves)
const w00 = axes.c2p(0, 0);
const w11 = axes.c2p(1, 1);
const ux = w11[0] - w00[0];
const uy = w11[1] - w00[1];
function toData(pt) { return [(pt[0] - w00[0]) / ux, (pt[1] - w00[1]) / uy]; }

await scene.play(new Create(axes));
const axLabels = axes.getAxisLabels();
await scene.play(new FadeIn(axLabels));

// Mirror line y = x
const mirror = new Line({ start: axes.c2p(-3, -3), end: axes.c2p(4, 4), color: GRAY });
mirror.setStrokeWidth(2);
const mirrorLabel = new MathTex({ latex: 'y = x', color: GRAY });
await mirrorLabel.waitForRender();
mirrorLabel.moveTo(axes.c2p(3.4, 2.7));
await scene.play(new AnimationGroup([new Create(mirror), new Write(mirrorLabel)]));

// y = e^x
const expCurve = axes.plot(x => Math.exp(x), { color: BLUE, xRange: [-3, 1.386], numSamples: 300 });
const expLabel = new MathTex({ latex: 'y = e^x', color: BLUE });
await expLabel.waitForRender();
expLabel.moveTo(axes.c2p(2.0, 3.3));
await scene.play(new AnimationGroup([new Create(expCurve), new Write(expLabel)]));

// Sample points on e^x reflect across y = x
const samples = [-2, -1, 0, 0.7, 1.2];
const sDots = samples.map(sv => new Dot({ point: axes.c2p(sv, Math.exp(sv)), color: YELLOW }));
await scene.play(new AnimationGroup(sDots.map(d => new FadeIn(d))));
await scene.play(new AnimationGroup(sDots.map(d => {
  const c = d.getCenter();
  const dc = toData(c);
  const tgt = axes.c2p(dc[1], dc[0]);
  return new Shift(d, { direction: [tgt[0] - c[0], tgt[1] - c[1], 0] });
})));
await scene.wait(0.5);

// y = ln(x) appears where the reflected points landed
const logCurve = axes.plot(x => Math.log(x), { color: ORANGE, xRange: [0.0498, 4], numSamples: 300 });
const logLabel = new MathTex({ latex: 'y = \\ln(x)', color: ORANGE });
await logLabel.waitForRender();
logLabel.moveTo(axes.c2p(3.2, 0.7));
await scene.play(new AnimationGroup([new Create(logCurve), new Write(logLabel), ...sDots.map(d => new FadeOut(d))]));

// Right-hand explanation column
const title = new Text({ text: 'Inverses by Reflection', color: WHITE, fontSize: 28 });
title.moveTo([4.35, 2.9, 0]);
const id1 = new MathTex({ latex: 'e^{\\ln(x)} = x' });
await id1.waitForRender();
id1.moveTo([4.35, 1.95, 0]);
const id2 = new MathTex({ latex: '\\ln(e^x) = x' });
await id2.waitForRender();
id2.moveTo([4.35, 1.25, 0]);
const swapTex = new MathTex({ latex: '(a, e^a) \\longleftrightarrow (e^a, a)' });
await swapTex.waitForRender();
swapTex.moveTo([4.35, 0.3, 0]);
const hint = new Text({ text: 'Drag the dots!', color: GOLD, fontSize: 26 });
hint.moveTo([4.35, -0.6, 0]);
await scene.play(new Write(title));
await scene.play(new AnimationGroup([new FadeIn(id1), new FadeIn(id2), new FadeIn(swapTex), new FadeIn(hint)]));

// Interactive mirrored pair of points
let a = 0.5;
const clampA = v => Math.max(-2.5, Math.min(1.3, v));

const dotP = new Dot({ point: axes.c2p(a, Math.exp(a)), color: BLUE });
const dotQ = new Dot({ point: axes.c2p(Math.exp(a), a), color: ORANGE });
const seg = new Polygon({ vertices: [axes.c2p(a, Math.exp(a)), axes.c2p(Math.exp(a), a)], color: GRAY });
seg.setStrokeWidth(2).setFillOpacity(0);
const mInit = (a + Math.exp(a)) / 2;
const foot = new Dot({ point: axes.c2p(mInit, mInit), color: WHITE });
foot.scale(0.55);

dotP.addUpdater(() => dotP.moveTo(axes.c2p(a, Math.exp(a))));
dotQ.addUpdater(() => dotQ.moveTo(axes.c2p(Math.exp(a), a)));
seg.addUpdater(() => seg.setVertices([axes.c2p(a, Math.exp(a)), axes.c2p(Math.exp(a), a)]));
foot.addUpdater(() => { const mm = (a + Math.exp(a)) / 2; foot.moveTo(axes.c2p(mm, mm)); });

await scene.play(new AnimationGroup([new FadeIn(seg), new FadeIn(foot), new FadeIn(dotP), new FadeIn(dotQ)]));

// Dragging either point updates 'a'; updaters snap both to the curves
makeDraggable(dotP, scene, { onDrag: (mob) => { a = clampA(toData(mob.getCenter())[0]); } });
makeDraggable(dotQ, scene, { onDrag: (mob) => { a = clampA(toData(mob.getCenter())[1]); } });
makeHoverable(dotP, scene, { hoverScale: 1.5 });
makeHoverable(dotQ, scene, { hoverScale: 1.5 });

const controls = new Controls(scene, { position: 'bottom-right' });
controls.addSlider({ label: 'a', min: -2.5, max: 1.3, value: 0.5, step: 0.01, onChange: (v) => { a = v; } });
controls.addButton({ label: 'Reset', onClick: () => { a = 0.5; } });

await scene.wait(999999);"
}

